// WordPress support: its functions, classes and constants join PHP's own in completion, hovers
// and parameter hints, and hook names complete inside add_action('…'), add_filter('…') and friends.
//
// The data (data/wp-stubs.js, about 1.7 MB, generated by scripts/build-wp-stubs.js) is only
// loaded when the open file belongs to a WordPress site.
(() => {
  'use strict';

  const HOOK_CALL = /\b(add_action|remove_action|has_action|do_action|do_action_ref_array|did_action|doing_action|add_filter|remove_filter|has_filter|apply_filters|apply_filters_ref_array|did_filter|doing_filter)\s*\(\s*['"]([^'"]*)$/;

  let host = null;
  let data = null;
  let loading = null;

  function load() {
    loading ||= new Promise((resolve) => {
      const script = document.createElement('script');
      script.src = 'data/wp-stubs.js';
      script.onload = () => resolve(window.CPM_WP_STUBS || null);
      script.onerror = () => resolve(null);
      document.head.append(script);
    }).then(async (stubs) => {
      const docs = window.CPM_PHP_DOCS;
      // WordPress's names are added to PHP's built-in ones, so those have to be there first.
      if (!stubs || !docs || !(await docs.load())) return null;
      docs.extend(stubs);
      data = stubs;
      return data;
    });
    return loading;
  }

  // Called when a PHP file is shown. Loads the data once, if the file is part of a WordPress site.
  async function check(path) {
    if (!host || loading) return;
    const mode = host.mode();
    if (mode === 'off') return;
    let found = mode === 'on' || /\/wp-(?:content|includes|admin)\//.test(path);
    if (!found) {
      const files = await host.files().catch(() => []);
      found = files.some((item) => (item.file === 'wp-load.php' || item.file === 'wp-config.php') && path.startsWith(`${item.dir}/`));
    }
    if (found && host.mode() !== 'off') load();
  }

  function register(monaco, hostApi) {
    host = hostApi;
    const Kind = monaco.languages.CompletionItemKind;
    monaco.languages.registerCompletionItemProvider(['php', 'blade'], {
      triggerCharacters: ['\'', '"'],
      provideCompletionItems(model, position) {
        if (!data || host.mode() === 'off') return { suggestions: [] };
        const line = model.getLineContent(position.lineNumber).slice(0, position.column - 1);
        const call = HOOK_CALL.exec(line);
        if (!call) return { suggestions: [] };
        const actions = call[1].includes('action');
        // Hook names contain dashes, slashes and {$placeholders}: replace everything since the quote.
        const range = {
          startLineNumber: position.lineNumber,
          endLineNumber: position.lineNumber,
          startColumn: position.column - call[2].length,
          endColumn: position.column,
        };
        return {
          suggestions: Object.entries(actions ? data.h.a : data.h.f).map(([name, [description, params]]) => ({
            label: name,
            kind: Kind.Event,
            insertText: name,
            filterText: name,
            detail: actions ? 'WordPress action' : 'WordPress filter',
            documentation: { value: `${description || ''}${params ? `\n\n\`\`\`php\n${params}\n\`\`\`` : ''}` },
            sortText: `0${name}`,
            range,
          })),
        };
      },
    });
  }

  window.CPM_WORDPRESS = { register, check, get loaded() { return Boolean(data); } };
})();
